import { FilePreviewCore, withPlugins } from "vane-file-preview";
import { createImagePreviewPlugin } from "vane-file-preview/custom-plugins/ImagePreviewPlugin";

const plugins = [createImagePreviewPlugin({ maxZoom: 8, minZoom: 0.25 })];
const Preview = withPlugins(FilePreviewCore, { plugins });

<Preview
  file={{ name: "cover.png", size: 204800, type: "image/png", extension: "png", url: "/cover.png" }}
  containerStyle={{ height: 420 }}
/>;
